 {page==='account'&&<div className="container page-wrap"><div className="page-title"><div><span className="eyebrow">Forma 3D / ACCOUNT</span><h1>{t('С возвращением, Алексей','Xush kelibsiz, Aleksey')}</h1></div><span className="demo-account">{t('Демонстрационный кабинет','Demo kabinet')}</span></div><div className="account-layout"><aside className="account-sidebar"><div className="profile"><span>А</span><div><strong>{t('Алексей','Aleksey')}</strong><small>+998 90 ••• •• 42</small></div></div>{[['orders',Box,t('Мои заказы','Buyurtmalarim')],['printers',Printer,t('Мои принтеры','Printerlarim')],['addresses',MapPin,t('Адреса','Manzillar')],['company',Building2,t('Реквизиты','Rekvizitlar')],['quick',Layers3,t('Быстрый заказ','Tezkor buyurtma')],['favorites',Heart,t('Избранное','Sevimlilar')]].map(([v,Icon,l])=>{const I=Icon as typeof Box;return <button key={v as string} className={accountTab===v?'active':''} onClick={()=>setAccountTab(v as string)}><I size={19}/>{l as string}</button>})}</aside><div className="account-content">{accountTab==='orders'&&<><div className="section-heading"><h2>{t('Мои заказы','Buyurtmalarim')}</h2><span className="muted">2 {t('заказа','buyurtma')}</span></div>{[[0,'FM-1024',t('28 сентября 2026','28 sentabr 2026'),t('Доставлен','Yetkazildi')],[1,'FM-0987',t('10 сентября 2026','10 sentabr 2026'),t('Доставлен','Yetkazildi')]].map(([i,id,date,status])=><div className="past-order" key={id as string}><div className="past-order-top"><strong>#{id}</strong><span>{date as string}</span><b>{status as string}</b></div><div className="past-order-items">{products.slice(Number(i),Number(i)+2).map(p=><div key={p.id}><img src={`/images/${p.image}`} alt={p.name}/><span>{p.name}<small>{t(p.color,p.uzColor)} · 2 {t('шт.','dona')}</small></span></div>)}</div><div className="past-order-bottom"><strong>{money(products.slice(Number(i),Number(i)+2).reduce((s,p)=>s+(p.price??0)*2,0))} {t('сум','so‘m')}</strong><button className="button outline small" onClick={()=>{products.slice(Number(i),Number(i)+2).forEach(p=>add(p,2));nav('cart')}}><RotateCcw size={16}/>{t('Повторить заказ','Buyurtmani takrorlash')}</button></div></div>)}</>}{accountTab==='printers'&&<><h2>{t('Мои принтеры','Printerlarim')}</h2><p className="muted">{t('Совместимые товары под вашу модель.','Modelingizga mos mahsulotlar.')}</p><div className="printer-card"><Printer size={52}/><div><strong>Bambu Lab {myPrinter}</strong><span>{t('Основной принтер','Asosiy printer')}</span></div></div><label>{t('Модель принтера','Printer modeli')}<SelectControl label="Printer" value={myPrinter} onChange={setMyPrinter} options={PRINTER_MODELS.map(v=>[v,v])}/></label><button className="button dark" onClick={()=>{reset();setPrinter(myPrinter);setGroup('parts');nav('catalog')}}>{t('Подобрать запчасти','Ehtiyot qismlarni tanlash')}</button></>}{accountTab==='addresses'&&<><h2>{t('Адрес доставки','Yetkazish manzili')}</h2><form className="account-form" onSubmit={e=>{e.preventDefault();setAddressSaved(true);toast.success(t('Адрес сохранён в демо','Manzil demoda saqlandi'))}}><label>{t('Адрес','Manzil')}<input defaultValue={t('Ташкент, улица Амира Темура, 15','Toshkent, Amir Temur ko‘chasi, 15')} required/></label><label>{t('Комментарий','Izoh')}<input placeholder={t('Этаж, подъезд, домофон','Qavat, kirish, domofon')}/></label><button className="button dark" type="submit">{addressSaved?t('Сохранено','Saqlandi'):t('Сохранить адрес','Manzilni saqlash')}</button></form></>}{accountTab==='company'&&<><h2>{t('Реквизиты компании','Kompaniya rekvizitlari')}</h2><p className="muted">{t('Подключите B2B-аккаунт для счетов и индивидуального прайса.','Hisoblar va individual narxlar uchun B2B kabinetini ulang.')}</p><button className="button dark" onClick={()=>nav('business')}>{t('Заявка на B2B','B2B uchun ariza')}</button><div className="document-row"><FileText/><span>{t('Счета, договор и акты','Hisoblar, shartnoma va dalolatnomalar')}<small>{t('Здесь появятся документы компании','Bu yerda kompaniya hujjatlari paydo bo‘ladi')}</small></span></div></>}{accountTab==='quick'&&<><span className="eyebrow">Forma 3D / B2B</span><h2>{t('Заказ по артикулу','Artikul bo‘yicha buyurtma')}</h2><p className="muted">{t('Добавьте нужное количество в корзину. Оптовая цена применится автоматически.','Kerakli miqdorni savatga qo‘shing. Ulgurji narx avtomatik qo‘llanadi.')}</p><div className="quick-order"><Table><TableHeader><TableRow><TableHead>{t('Артикул','Artikul')}</TableHead><TableHead>{t('Количество','Miqdor')}</TableHead><TableHead>{t('Цена / шт.','Narx / dona')}</TableHead></TableRow></TableHeader><TableBody><TableRow><TableCell><SelectControl label={t('Артикул','Artikul')} value={quickSku} onChange={v=>{setQuickSku(v);setQuickQty(n=>Math.min(n,products.find(p=>p.id===v)!.stock??1))}} options={products.filter(p=>canOrder(p)).map(p=>[p.id,`${title(p)} · ${t(p.color,p.uzColor)}`])}/></TableCell><TableCell><input type="number" min={1} max={products.find(p=>p.id===quickSku)?.stock||1} value={quickQty} aria-label={t('Количество','Miqdor')} onChange={e=>setQuickQty(Math.max(1,Math.min(products.find(p=>p.id===quickSku)?.stock||1,Number(e.target.value)||1)))}/></TableCell><TableCell>{money(unitPrice(products.find(p=>p.id===quickSku)!,quickQty))}</TableCell></TableRow></TableBody></Table><div className="quick-actions"><button className="button dark" onClick={()=>add(products.find(p=>p.id===quickSku)!,quickQty)}>{t('Добавить в корзину','Savatga qo‘shish')}<ShoppingBag size={17}/></button><button className="button outline" onClick={()=>setNotice(t('Импорт Excel','Excel importi'))}><FileText size={17}/>{t('Загрузить Excel','Excel yuklash')}</button></div></div></>}{accountTab==='favorites'&&<><h2>{t('Избранное','Sevimlilar')}</h2>{favorite.length?<div className="product-grid catalog-grid">{products.filter(p=>favorite.includes(p.id)).map(p=><React.Fragment key={p.id}>{ProductCard({p})}</React.Fragment>)}</div>:<div className="empty-state"><Heart size={40}/><p>{t('Сохраните товары сердечком в каталоге.','Katalogda yurakcha bilan mahsulotlarni saqlang.')}</p><button className="button dark" onClick={()=>openCatalog()}>{t('Открыть каталог','Katalogni ochish')}</button></div>}</>}<p className="demo-note">{t('Это пример кабинета. Вход по SMS и сохранение данных подключим на следующем этапе.','Bu kabinet namunasi. SMS orqali kirish va ma’lumotlarni saqlash keyingi bosqichda ulanadi.')}</p></div></div></div>}
 {page==='delivery'&&<div className="container page-wrap info-page"><span className="eyebrow">Forma 3D / DELIVERY</span><h1>{t('От нашего склада — к вашему принтеру','Omborimizdan printeringizgacha')}</h1><p className="info-intro">{t('Доставка по Ташкенту и во все регионы Узбекистана.','Toshkent va O‘zbekistonning barcha viloyatlariga yetkazish.')}</p><div className="delivery-cards">{[[Truck,t('Курьер по Ташкенту','Toshkent bo‘ylab kuryer'),t('Сегодня / завтра','Bugun / ertaga'),t('При заказе до 14:00 — в тот же день. После — на следующий.','14:00 gacha buyurtma — shu kuni. Keyin — ertasi kuni.'),'25 000'],[Box,t('Регионы Узбекистана','O‘zbekiston viloyatlari'),t('1–4 дня','1–4 kun'),t('Курьерской службой. Стоимость зависит от адреса и веса.','Kuryer xizmati bilan. Narx manzil va vaznga bog‘liq.'),'45 000+'],[MapPin,t('Самовывоз','Olib ketish'),t('Через 1 час','1 soatdan keyin'),t('После подтверждения менеджером. Адрес склада уточняется.','Menejer tasdiqlagandan keyin. Ombor manzili aniqlanadi.'),t('Бесплатно','Bepul')]].map(([Icon,title,time,body,price],i)=>{const I=Icon as typeof Truck;return <article key={i}><I size={33}/><h2>{title as string}</h2><strong>{time as string}</strong><p>{body as string}</p><span>{price as string} {i<2?t('сум','so‘m'):''}</span></article>})}</div><p className="demo-note">{t('Тарифы приведены как пример. Окончательные условия появятся перед запуском.','Tariflar namuna sifatida berilgan. Yakuniy shartlar ishga tushirishdan oldin belgilanadi.')}</p><section className="payment-info"><h2>{t('Как можно оплатить','To‘lov usullari')}</h2><div className="payment-logos"><span>payme</span><span>CLICK</span><span>UZCARD</span><span>HUMO</span></div><p>{t('Онлайн, по счёту для компаний или при получении в Ташкенте. В демонстрационной версии платежи не подключены.','Onlayn, kompaniyalar uchun hisob orqali yoki Toshkentda olganda. Demo versiyada to‘lovlar ulanmagan.')}</p></section></div>}
 {page==='contacts'&&<div className="container page-wrap info-page"><span className="eyebrow">Forma 3D / ABOUT</span><h1>{t('Хорошей печати нужен хороший материал','Yaxshi bosma yaxshi materialdan boshlanadi')}</h1><div className="about-layout"><div><h2>{t('Мы — Forma 3D','Biz — Forma 3D')}</h2><p>{t('Магазин материалов, расходников и запчастей для 3D-печати в Узбекистане. Помогаем частным мастерам, принт-фермам и образовательным организациям подобрать материалы для своих проектов.','O‘zbekistonda 3D bosma uchun materiallar, sarf materiallari va ehtiyot qismlar do‘koni. Ustalar, print-fermalar va ta’lim tashkilotlariga loyihalar uchun material tanlashda yordam beramiz.')}</p><p>{t('Forma 3D — всё для вашей 3D-печати. Предлагаем оригинальную продукцию Bambu Lab и помогаем подобрать материалы и расходники для ваших проектов.','Forma 3D — 3D bosmangiz uchun hamma narsa. Original Bambu Lab mahsulotlarini taklif qilamiz va loyihalaringiz uchun material hamda sarf materiallarini tanlashda yordam beramiz.')}</p></div><div className="contact-card"><MapPin size={28}/><h2>{t('Ташкент, Узбекистан','Toshkent, O‘zbekiston')}</h2><p>{t('Адрес склада, часы работы и контакты будут добавлены перед запуском.','Ombor manzili, ish vaqti va kontaktlar ishga tushirishdan oldin qo‘shiladi.')}</p><button className="button dark" onClick={()=>setNotice('Telegram')}><MessageCircle size={18}/>{t('Написать в Telegram','Telegramda yozish')}</button><span className="demo-note">{t('Контакт менеджера пока не подключён.','Menejer kontakti hali ulanmagan.')}</span></div></div></div>}
 {page==='knowledge'&&<div className="container page-wrap"><span className="eyebrow">Forma 3D / KNOWLEDGE</span><div className="page-title"><h1>{t('От катушки к результату','G‘altakdan natijagacha')}</h1></div><div className="guide-grid all-guides">{guides.map((g,i)=><button key={i} className="guide-card" onClick={()=>setArticle(i)}><div className="guide-cover" style={{background:g.color}}><span>Forma 3D / GUIDE 0{i+1}</span><strong>{g.mark}</strong><span className="guide-cover-bottom">{t('НА ПРАКТИКЕ','AMALIYOTDA')}<Plus size={20}/></span></div><div className="guide-meta">{t(g.category,g.uzCat)}<span>{g.minutes} {t('мин','daq')}</span></div><h3>{t(g.title,g.uz)}</h3></button>)}</div></div>}
 {['offer','privacy','returns'].includes(page)&&<div className="container page-wrap legal-page"><span className="eyebrow">Forma 3D / INFORMATION</span><h1>{page==='offer'?t('Публичная оферта','Ommaviy oferta'):page==='privacy'?t('Конфиденциальность','Maxfiylik'):t('Возврат и обмен','Qaytarish va almashtirish')}</h1><div className="legal-notice"><FileText size={28}/><h2>{t('Страница подготовлена для финального текста','Sahifa yakuniy matn uchun tayyor')}</h2><p>{t('Условия магазина, реквизиты продавца и юридические документы добавим после согласования с заказчиком. В этой версии реальные заказы и платежи не принимаются.','Do‘kon shartlari, sotuvchi rekvizitlari va huquqiy hujjatlar buyurtmachi bilan kelishilgandan keyin qo‘shiladi. Ushbu versiyada haqiqiy buyurtmalar va to‘lovlar qabul qilinmaydi.')}</p><Link className="plain-link" to="contacts">{t('О магазине','Do‘kon haqida')}</Link></div></div>}
