 <footer className="footer"><div className="container footer-top"><div className="footer-brand"><Link to="" className="logo">Forma <span className="logo-3d">3D</span></Link><p>{t('Всё для вашей 3D-печати.','3D bosmangiz uchun hamma narsa.')}</p><span>{t('Ташкент, Узбекистан','Toshkent, O‘zbekiston')}</span></div><div><strong>{t('Каталог','Katalog')}</strong><button onClick={()=>openCatalog('PLA')}>PLA</button><button onClick={()=>openCatalog('PETG')}>PETG</button><button onClick={()=>openCatalog('Все','parts')}>{t('Запчасти и расходники','Ehtiyot qismlar')}</button></div><div><strong>{t('Покупателям','Xaridorlarga')}</strong><Link to="delivery">{t('Доставка и оплата','Yetkazish va to‘lov')}</Link><Link to="returns">{t('Возврат и обмен','Qaytarish va almashtirish')}</Link><Link to="knowledge">{t('База знаний','Bilimlar bazasi')}</Link><Link to="contacts">{t('О нас и контакты','Biz haqimizda')}</Link></div><div><strong>{t('Для ваших проектов','Loyihalaringiz uchun')}</strong><Link to="business">{t('Оптовые закупки','Ulgurji xaridlar')}</Link><Link to="account">{t('Личный кабинет','Shaxsiy kabinet')}</Link><button className="footer-telegram" onClick={()=>setNotice('Telegram')}><MessageCircle size={17}/>Telegram</button><div className="language"><button className={!uz?'active':''} onClick={()=>{const next=path.replace(/^\/(ru|uz)/,'/ru');history.pushState({},'',next);setPath(next)}}>RU</button><span>/</span><button className={uz?'active':''} onClick={()=>{const next=path.replace(/^\/(ru|uz)/,'/uz');history.pushState({},'',next);setPath(next)}}>UZ</button></div></div></div><div className="container footer-bottom"><span>© 2026 Forma 3D. {t('Демонстрационная версия.','Namoyish versiyasi.')}</span><div><Link to="offer">{t('Оферта','Oferta')}</Link><Link to="privacy">{t('Конфиденциальность','Maxfiylik')}</Link></div><span className="payment-mini">payme <b>CLICK</b> HUMO</span></div></footer>
